{
  "technical_and_design_decisions": [
    "Extend Spring XD Kafka source with a deployment property 'startingOffset' (earliest/latest/timestamp) applied only at stream deployment; runtime progress is committed to Kafka and survives crashes.",
    "For U2 TBD, assume undeploy/redeploy without explicit startingOffset resumes from last committed offset (or latest if none); explicit offset forces re-read from that point.",
    "Use Kafka consumer manual partition assignment (assign API) for U3 to pre-allocate partitions across Kafka source modules at deployment, avoiding dynamic rebalance.",
    "For U4, implement a deployment-time partition allocator (using ZooKeeper/Redis) that statically maps message bus partitions to container nodes, disabling dynamic rebalancing.",
    "Implement reactor-stream processor (U6) using Project Reactor Flux window operators and expression evaluation to compute aggregates (min, avg, etc.) over time windows.",
    "Implement microbatching (U7) via a 'batchInterval' option that buffers messages in source/sink modules and flushes on interval or size threshold.",
    "For U5, create a Spark Streaming POC that consumes from XD message bus and produce a design recommendation document; no production integration in this increment.",
    "Provision performance infrastructure (U8) on Rackspace using Ansible scripts to deploy Kafka and XD containers for benchmarking."
  ],
  "assumptions": [
    "A single experienced developer performs all work; estimates are work-hours, not calendar time.",
    "Existing Spring XD codebase is used; no upgrade to Spring Framework 6 / Java 17 is required for this increment.",
    "Kafka version supports manual partition assignment (Kafka 0.10+).",
    "Wiki documentation refers to existing internal project wiki; effort covers authoring content only.",
    "Rackspace cloud credentials and account are available; only setup and scripting effort is estimated, not infrastructure cost.",
    "Effort includes unit testing and basic integration testing but excludes extensive long-running soak tests and unrelated product management."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and TBD resolution",
      "activity_description": "Analyze user stories, resolve ambiguous TBD in U2 regarding undeploy/redeploy behavior, and finalize acceptance criteria for the increment.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Design Kafka source starting offset control",
      "activity_description": "Design configuration model and lifecycle for U2: startingOffset property, deployment handling, and crash-safe offset commits.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Kafka source starting offset control",
      "activity_description": "Code the Kafka source changes for U2, including unit tests and integration with XD deployment service.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "Design Kafka partition pre-allocation (U3)",
      "activity_description": "Design static partition assignment scheme for Kafka source modules at stream deployment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement Kafka partition pre-allocation (U3)",
      "activity_description": "Implement manual assign logic and deployment-time partition distribution for Kafka sources, with tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "Design message bus partition pre-allocation (U4)",
      "activity_description": "Design coordinator/allocator for message bus partitions across container nodes to avoid rebalancing.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement message bus partition pre-allocation (U4)",
      "activity_description": "Implement allocator service and integrate with bus subscribers; disable dynamic rebalance for allocated streams.",
      "most_likely_effort": 56
    },
    {
      "activity_id": "A8",
      "activity_name": "Spark investigation, POC, and design (U5)",
      "activity_description": "Research Spark Streaming integration, build a proof-of-concept module, and produce design recommendation for XD.",
      "most_likely_effort": 80
    },
    {
      "activity_id": "A9",
      "activity_name": "Design reactor-stream processor (U6)",
      "activity_description": "Design reactor-stream module parameters (timeWindow, field, expressions) and windowing/aggregation pipeline.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "Implement reactor-stream processor (U6)",
      "activity_description": "Implement the reactor-stream processor module with time-window operations and expression evaluation; unit tests.",
      "most_likely_effort": 64
    },
    {
      "activity_id": "A11",
      "activity_name": "Design microbatching capability (U7)",
      "activity_description": "Design batchInterval option for sources/sinks, buffering strategy, and flush triggers.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A12",
      "activity_name": "Implement microbatching capability (U7)",
      "activity_description": "Implement microbatching in XD modules including http source and log sink examples; tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A13",
      "activity_name": "Setup performance testing infrastructure (U8)",
      "activity_description": "Provision Rackspace servers, install Kafka and XD, create benchmarking scripts and baseline tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A14",
      "activity_name": "Wiki documentation (U1)",
      "activity_description": "Author wiki pages for new sources, sinks, processor modules, and features delivered in this increment.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A15",
      "activity_name": "Integration testing and performance benchmarking",
      "activity_description": "Perform end-to-end integration tests across all new features and run performance benchmarks on Rackspace setup.",
      "most_likely_effort": 40
    }
  ],
  "reported_total": {
    "most_likely_effort": 560
  }
}

